contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive contract: caller deposits 'amt' and we assert their recorded balance increased by amt.
    function runTest(uint amt) public payable {
        // require enough ether provided to this call to forward to c
        require(amt > 0, "amt must be positive");
        require(address(this).balance >= amt, "insufficient balance to deposit");

        // read balance before
        uint before = c.balances(address(this));

        // perform deposit to c by forwarding amt
        c.Deposit{value: amt}();

        // read balance after
        uint after = c.balances(address(this));

        // The correct contract increases the stored balance by amt; the mutant decreases it, so this distinguishes them.
        assert(after >= before + amt);
    }

    // allow funding this contract for the test
    receive() external payable {}
}

