pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - depositor: the address that will deposit
    // - depositAmt: the amount to deposit (in wei)
    // - collectAmt: the amount to attempt to collect
    // General rule being tested (single assert at end): after a deposit and then a Collect by possibly another actor,
    // the reference implementation ensures balances for any observed key are consistent with Deposit increasing balances;
    // the mutant (which subtracts on Deposit) will produce a differing balances(k) for some fuzzed inputs.
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // keep depositor non-zero to be an admissible actor
        vm.assume(depositor != address(0));
        // bound depositAmt to a reasonable range to avoid overflow in VM balances
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // fund depositor so they can send Ether
        vm.deal(depositor, depositAmt + 1 ether);

        // Make depositor call Deposit() via receive path (transfer of Ether triggers Deposit)
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: depositAmt}("");
        // require that Deposit call succeeded in the environment under test
        // If Deposit reverted, then contract state didn't change and nothing to assert about balances change after Collect
        // but we continue only if deposit succeeded
        if (!okDeposit) return;

        // Record balances mapping for an arbitrary key we'll query after Collect: use depositor as the key
        uint256 before_bal = c.balances(depositor);

        // Now have depositor call Collect(collectAmt)
        vm.prank(depositor);
        bool okCollect;
        try c.Collect(collectAmt) {
            okCollect = true;
        } catch {
            okCollect = false;
        }

        // Query balances for the same key after Collect
        uint256 after_bal = c.balances(depositor);

        // General invariant that the reference satisfies for all inputs:
        // After a successful Deposit (we ensured deposit call succeeded), the mapping entry for depositor is >= before_bal.
        // In the reference Deposit increases the recorded balance by depositAmt, so before_bal >= 0 always and after Collect
        // should reflect only permitted subtractions by Collect when conditions met. However, the single assertion we check
        // here is that after a Deposit (which succeeded), the recorded balance is at least zero and that if Collect returned
        // successfully then the recorded balance after Collect is equal to before_bal - collectAmt (i.e., Collect only reduces
        // by the requested amount when permitted). The mutant that subtracts on Deposit will lead to different recorded balances
        // for some fuzzed inputs (e.g., depositAmt>0) and cause this assertion to fail.

        // Implementing a conservative universal assertion that the reference always satisfies for all admissible inputs:
        // If Collect returned true then the recorded after_bal is <= before_bal (Collect cannot increase balances),
        // and if Collect returned true then the difference is at most collectAmt (it deducts exactly collectAmt on success).
        // We assert that when Collect succeeded: before_bal >= after_bal && (before_bal - after_bal) == (okCollect ? ((before_bal >= collectAmt && before_bal >= c.MinSum()) ? collectAmt : 0) : 0)
        // But MinSum is public, so we can read it. To keep the assertion single and simple while still distinguishing mutant,
        // assert that if Collect succeeded then after_bal <= before_bal. The mutant can make before_bal smaller on Deposit and
        // thus produce a case where after_bal > before_bal when Collect does nothing; however, to ensure the reference always
        // satisfies and mutant can violate, we use the stronger property: after a successful Deposit, before any Collect, balances
        // is >= depositAmt (i.e., Deposit increased it). We recorded before_bal immediately after Deposit, so before_bal >= depositAmt
        // holds in the reference but fails in the mutant.

        // Single decisive assertion: the recorded balance after Deposit (before_bal) is >= depositAmt.
        // This is true for the reference for all inputs (Deposit increases by msg.value); the mutant that subtracts on Deposit
        // will make before_bal < depositAmt for some fuzzed inputs (and normally depositAmt>0). We made depositAmt >=1 above.
        assertTrue(before_bal >= depositAmt);
    }
}

