pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: depositor (actor) and amounts for deposit and collect.
    // General rule: for any depositor, after a successful Deposit of d and then a successful Collect(w) with w<=previous balance,
    // the public getter balances(depositor) equals previous_balance - w (i.e., Collect does not unexpectedly decrease other balances),
    // equivalently balances(depositor) does not increase as a result of Collect.
    // We implement this by performing one deposit (via receive) and then Collect and asserting the final balances equals initial+deposit - withdraw.
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 withdrawAmt) public {
        // Keep inputs in a wide admissible domain but meaningful: depositor non-zero and amounts small enough to avoid overflow in test env
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 1, 1 ether);
        withdrawAmt = bound(withdrawAmt, 0, 1 ether);

        // Fund depositor externally so it can send ETH
        vm.deal(depositor, depositAmt + 1 ether);

        // Record pre-state balance getter
        uint256 before = c.balances(depositor);

        // depositor performs Deposit by sending ether to contract (receive -> Deposit)
        vm.prank(depositor);
        (bool sent,) = payable(address(c)).call{value: depositAmt}('');
        require(sent, "send failed");

        uint256 afterDeposit = c.balances(depositor);

        // ensure deposit recorded at least reflects monotonic non-decrease in reference
        // We allow withdrawAmt up to afterDeposit so Collect may succeed or silently do nothing per contract
        withdrawAmt = bound(withdrawAmt, 0, afterDeposit);

        // Attempt Collect from depositor and record success
        bool ok;
        vm.prank(depositor);
        try c.Collect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: if Collect succeeded, the new balances(depositor) equals afterDeposit - withdrawAmt
        // This is a general invariant the reference satisfies for all inputs; the mutant will fail for some fuzzed inputs
        if (ok) {
            uint256 finalBal = c.balances(depositor);
            assertTrue(finalBal == (afterDeposit - withdrawAmt));
        } else {
            // If Collect reverted / did nothing, then balances must be unchanged
            uint256 finalBal = c.balances(depositor);
            assertTrue(finalBal == afterDeposit);
        }
    }
}

