contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (who will deposit), collector (who will Collect), and amounts
    function testFuzz_property(address depositor, address collector, uint256 depAmt, uint256 collectAmt) public {
        // keep addresses non-zero and distinct to avoid accidental self-calls or zero-address issues
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));
        // bound amounts to reasonable ranges so deposits/withdrawals fit within EVM balance setup
        depAmt = bound(depAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Set up contract parameters before initialization
        // leave MinSum = 0 (default) so that Collect may proceed when balance sufficient

        // Fund depositor externally so they can call Deposit (Deposit uses msg.value)
        vm.deal(depositor, depAmt);
        // depositor makes a deposit to increase their tracked balance in reference
        vm.prank(depositor);
        c.Deposit{value: depAmt}();

        // record balances snapshot for collector and depositor before Collect
        uint256 beforeCollector = c.balances(collector);
        uint256 beforeDepositor = c.balances(depositor);

        // Now attempt Collect from collector: if collector has insufficient balance, Collect is a no-op (reference)
        // We wrap call in try/catch to observe whether it reverted; Collect reverts only if the low-level send fails
        bool ok;
        vm.prank(collector);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE ASSERTION: in the reference, balances[collector] after the call is always >= 0
        // and if Collect succeeded then balances[collector] == beforeCollector - collectAmt (because Collect only transfers when balance>=MinSum and >= amount)
        // We assert the non-negativity and the expected decrease when ok is true by checking the public getter.
        uint256 afterCollector = c.balances(collector);

        // For all admissible inputs on the reference: afterCollector never underflows (is >= 0 by uint) and when Collect returned ok,
        // the recorded balance must equal the prior minus collectAmt.
        // Express this as a single boolean property to assertTrue over the contract's public getter.
        bool prop;
        if (ok) {
            prop = (afterCollector + collectAmt == beforeCollector);
        } else {
            // If Collect didn't complete (low-level send failed or preconditions not met), the reference guarantees no change to collector's balance
            prop = (afterCollector == beforeCollector);
        }

        assertTrue(prop);
    }
}

