pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (who will deposit and collect) and two amounts: depositAmt and collectAmt
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // admissible domain: depositor should be non-zero and amounts not absurdly large to avoid overflow in test harness
        vm.assume(depositor != address(0));
        depositAmt = bound(depositAmt, 1, type(uint128).max); // require at least 1 wei deposit
        collectAmt = bound(collectAmt, 0, type(uint128).max);

        // Fund depositor externally so they can send Ether to c
        vm.deal(depositor, depositAmt + 1 ether);

        // Make depositor perform Deposit by sending Ether via Deposit()
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Read balance before collect
        uint256 before = c.balances(depositor);

        // Ensure we only attempt to collect up to the recorded balance to keep within reference's guarded path
        // (the reference only transfers if balances[msg.sender] >= MinSum && balances[msg.sender] >= _am)
        // To ensure Collect will proceed, set MinSum to 0 before initializing
        c.SetMinSum(0);

        // Now attempt Collect with collectAmt but bound it to before so collect will be allowed when possible
        uint256 toCollect = collectAmt % (before + 1); // in [0, before]

        bool ok;
        try c.Collect(toCollect) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference: if Collect succeeded (ok==true) then balances[depositor] == before - toCollect.
        // If Collect reverted (ok==false), the public balances must remain equal to before (no change).
        // This single assertion encodes that universal property.
        if (ok) {
            assertTrue(c.balances(depositor) == before - toCollect);
        } else {
            assertTrue(c.balances(depositor) == before);
        }
    }
}

