pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and amounts to deposit and collect.
    // We must ensure the depositor has enough ETH to send deposit and that collect <= recorded balance.
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // Keep depositor a non-zero address
        vm.assume(depositor != address(0));
        // Bound amounts to reasonable ranges so vm.deal can work and overflow edgecases are avoided.
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Fund depositor externally so they can send ETH
        vm.deal(depositor, depositAmt);

        // depositor performs a Deposit by sending ETH to the contract (use receive -> Deposit)
        vm.prank(depositor);
        (bool okSend, ) = address(c).call{value: depositAmt}("");
        // require that the deposit call succeeded in order to proceed with the property check domain
        vm.assume(okSend);

        // read balance recorded for depositor before Collect
        uint256 before = c.balances(depositor);

        // Ensure we only attempt to Collect amounts that are <= recorded balance; if not, the Collect is a no-op per contract
        vm.assume(collectAmt <= before);

        // Have depositor call Collect(collectAmt). Capture success/failure.
        bool ok;
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Collect call (ok==true), the reference guarantees balances[depositor] == before - collectAmt.
        // We assert that whenever the Collect call returned/finished (didn't revert), the recorded balances equals before - collectAmt.
        // This is the single assertion reading c's public getter that the reference always satisfies and the mutant can break.
        if (ok) {
            uint256 after = c.balances(depositor);
            assertTrue(after == before - collectAmt);
        } else {
            // If Collect reverted, then the reference would not have allowed the withdraw; still assert that recorded balance is unchanged
            // (Collect revert implies no state change), so balances must equal before. This is also a property of the reference.
            uint256 after = c.balances(depositor);
            assertTrue(after == before);
        }
    }
}
